def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 98:
        for i in range(n - 1):
            if history[i][0] == 'D' and history[i + 1][1] == 'D':
                return 'C'
        return 'D'

    opp_C = 0
    opp_D = 0
    my_D = 0
    for a, b in history:
        if b == 'C':
            opp_C += 1
        else:
            opp_D += 1
        if a == 'D':
            my_D += 1

    if opp_C == 0:
        return 'D'

    after_my_D_C = 0
    after_my_D_D = 0
    last_D_idx = -1
    for i in range(n - 1):
        if history[i][0] == 'D':
            last_D_idx = i
            if history[i + 1][1] == 'C':
                after_my_D_C += 1
            else:
                after_my_D_D += 1

    if after_my_D_C >= 3 and after_my_D_D == 0:
        return 'D'

    last_opp = history[-1][1]
    last_my = history[-1][0]

    if last_opp == 'D':
        if last_my == 'D':
            return 'C'
        else:
            if opp_C > n * 0.7:
                return 'C'
            return 'D'
    else:
        if last_my == 'D':
            return 'C'
        if n >= 15:
            if last_D_idx == -1 or n - last_D_idx > 15:
                if opp_C > n * 0.8 and n < 90:
                    return 'D'
        return 'C'
